def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    yesterday_bids = []
    desperate_count = 0
    rich_count = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
                desperate_count += 1
            if opp.get('budget', 0) >= DAILY_SALARY * 4:
                rich_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                yesterday_bids.append(prev.get('bid', 0))

    if not alive:
        return max(0.0, min(float(budget), 18.0))

    players = len(alive) + 1
    expected_units = float(supply) / float(WATER_REQ)
    pressure = players - expected_units

    if pressure <= 0:
        base = 16.0
    elif pressure <= 1:
        base = 28.0
    elif pressure <= 2:
        base = 40.0
    else:
        base = 52.0

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        avg_prev = sum(yesterday_bids) / float(len(yesterday_bids))
        if max_prev >= 60:
            base = max(base, 46.0 if hp > 3 else 63.0)
        elif max_prev >= 45:
            base = max(base, min(58.0, max_prev + 2.0))
        else:
            base = max(base, avg_prev + 3.0)
    else:
        max_prev = 0.0

    if hp <= 2 or no_water_days >= 2:
        base = max(base, 64.0)
    elif hp <= 4 or no_water_days >= 1:
        base = max(base, 52.0)

    if desperate_count >= max(1, len(alive) // 2):
        base += 5.0
    if rich_count >= max(1, len(alive) // 2):
        base += 3.0

    if day >= 8:
        base += 4.0
    if day <= 2 and hp >= 6 and no_water_days == 0:
        base -= 4.0

    reserve = DAILY_SALARY * max(0, 10 - int(day)) * 0.18
    cap = max(0.0, float(budget) - reserve)
    if hp <= 3 or no_water_days >= 2:
        cap = float(budget)

    bid = min(base, cap, float(budget))
    if bid < 0:
        bid = 0.0
    return float(bid)

