def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Immediate reaction: if any opponent previously bid very high, slightly raise.
    # (We only use previous_trace from yesterday as required.)
    high_prev = None
    for _, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b_val = float(b)
                if high_prev is None or b_val > high_prev:
                    high_prev = b_val
            except Exception:
                pass

    # Baseline pressure based on supply closeness to my requirement.
    # If supply is tight (near 13), bid more; if abundant (near 25), bid less.
    tightness = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        tightness = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
    tightness = max(0.0, min(1.0, tightness))

    # Base bid fraction of daily salary.
    base_frac = 0.45 + 0.25 * tightness

    # If hp is low or I've had no water days, increase urgency.
    if hp <= 2.0:
        base_frac += 0.25
    elif hp <= 4.0:
        base_frac += 0.10

    if no_water_days >= 2:
        base_frac += 0.10

    # If opponents were bidding aggressively yesterday, counter slightly.
    if high_prev is not None:
        try:
            high_prev_f = float(high_prev)
            if high_prev_f >= DAILY_SALARY * 0.85:
                base_frac += 0.10
            elif high_prev_f >= DAILY_SALARY * 0.65:
                base_frac += 0.05
        except Exception:
            pass

    # Convert to bid amount; cap by budget.
    bid = DAILY_SALARY * base_frac

    # Ensure bid is at least enough to matter, but not excessive.
    # Also keep within budget.
    bid_min = DAILY_SALARY * 0.25
    bid_max = min(budget, DAILY_SALARY * 0.95)
    if bid < bid_min:
        bid = bid_min
    if bid > bid_max:
        bid = bid_max

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Look at yesterday's bids
    yesterday_max_bid = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_max_bid = max(yesterday_max_bid, prev['bid'])

    # Determine aggressiveness
    # If someone bid very high (>=85% of salary), they are aggressive
    if yesterday_max_bid >= DAILY_SALARY * 0.85:
        if my_status['hp'] > 3:
            # Conserve budget: bid low
            return min(my_status['budget'], DAILY_SALARY * 0.3)
        else:
            # Need water: bid high
            return min(my_status['budget'], DAILY_SALARY * 0.95)
    else:
        # Mild competition: outbid slightly or safe level
        if my_status['hp'] <= 2:
            return min(my_status['budget'], DAILY_SALARY * 0.9)
        else:
            target = max(DAILY_SALARY * 0.5, yesterday_max_bid + 1.5)
            return min(my_status['budget'], target)
